import React, { useState } from 'react';
import DepartmentDetails from './DepartmentDetails'; // Adjust path as needed

const WorkingTab = ({ selectedDepartment, handleDepartmentChange, saveWorkingData }) => {
  const [area, setArea] = useState('');
  const [cost, setCost] = useState('');
  const [clientName, setClientName] = useState('');

  // Handle input changes for area, cost, and client name
  const handleFieldChange = (e) => {
    const { name, value } = e.target;
    if (name === 'area') setArea(value);
    else if (name === 'cost') setCost(value);
    else if (name === 'clientName') setClientName(value);
  };

  // Handle form submission
  const handleSubmit = (e) => {
    e.preventDefault();
    // Save the entered data in the parent component (Dashboard)
    saveWorkingData(selectedDepartment, area, cost, clientName);
    // Reset the form after submission
    setArea('');
    setCost('');
    setClientName('');
  };

  return (
    <div className="working-box">
      <label htmlFor="select-department" className="select-label">
        Choose Department:
      </label>
      <select
        id="select-department"
        className="select-department"
        value={selectedDepartment}
        onChange={handleDepartmentChange}
      >
        {['Survey Department', 'Architecture Department', 'Urban Planning Department', 'Engineering Drawing Department', 'JDA Submission', 'GIS', 'Site Plan', 'Area Conversion', 'Sector SuperImpose', 'Print'].map(dept => (
          <option key={dept} value={dept}>{dept}</option>
        ))}
      </select>

      {selectedDepartment && (
        <form onSubmit={handleSubmit}>
          <div className="form-field">
            <label>Area:</label>
            <input
              type="text"
              name="area"
              value={area}
              onChange={handleFieldChange}
              required
            />
          </div>
          <div className="form-field">
            <label>Cost:</label>
            <input
              type="number"
              name="cost"
              value={cost}
              onChange={handleFieldChange}
              required
            />
          </div>
          <div className="form-field">
            <label>Client Name:</label>
            <input
              type="text"
              name="clientName"
              value={clientName}
              onChange={handleFieldChange}
              required
            />
          </div>
          <button type="submit" className="save-button">Save Working Data</button>
        </form>
      )}
    </div>
  );
};

export default WorkingTab;
